import re
import unicodedata
from typing import Any

# # ---------- 1) helper เช็กว่าเป็นตัว "คล้ายช่องว่าง" ไหม ----------

ZERO_WIDTH_CHARS = "\u0020\u200c\u200d\ufeff"  # zero width space/joiner/BOM

def is_space_like(ch: str) -> bool:
    """ตัวนี้จะถือว่าเป็น 'ช่องว่าง' ถ้า:
    - เป็น zero-width ที่เรารู้จัก
    - หรือ isspace() = True (tab, \n, NBSP, ฯลฯ)
    - หรือ category Unicode ขึ้นต้นด้วย 'Z' (พวก space แปลก ๆ)
    """
    if ch in ZERO_WIDTH_CHARS:
        return True
    if ch.isspace():
        return True
    cat = unicodedata.category(ch)
    if cat.startswith("Z"):
        return True
    return False


def normalize_space_like(text: str) -> str:
    """แปลงทุกตัวที่ is_space_like เป็น space ปกติ ' '"""
    if not text:
        return text
    return "".join(" " if is_space_like(c) else c for c in text)


# ---------- 2) logic ตามกฎที่คุณต้องการ ----------

def fix_spaces_and_duplicate_chars(text: str) -> str:
    """
    กติกา:
    - X + (ช่องว่าง >=2) + X  -> รวมเหลือ X ตัวเดียว (ไม่มีช่องว่าง)
      เช่น "สถา    านทูต" -> "สถานทูต"
    - ช่องว่าง >=2 แต่ตัวก่อน/หลังไม่เหมือนกัน -> เหลือ space เดียว
      เช่น "สถา    งานทูต" -> "สถา งานทูต"
    - ช่องว่างเดียว -> คงไว้
      เช่น "สถา งานทูต" -> "สถา งานทูต"
    """
    if not text:
        return text

    # 1) ให้ทุกช่องว่างทุกแบบกลายเป็น ' ' ก่อน
    text = normalize_space_like(text)

    chars = list(text)
    out: list[str] = []
    i = 0
    n = len(chars)

    while i < n:
        c = chars[i]

        if c != " ":
            out.append(c)
            i += 1
        else:
            # เก็บ run ของ space ต่อเนื่อง
            j = i
            while j < n and chars[j] == " ":
                j += 1
            gap_len = j - i

            prev = out[-1] if out else None
            next_char = chars[j] if j < n else None

            if gap_len >= 2:
                if prev is not None and next_char is not None and prev == next_char:
                    # เคส X [spaceหลายตัว] X -> รวมเป็น X ตัวเดียว (ตัดช่องว่าง+ตัวขวาออก)
                    i = j + 1
                    continue
                else:
                    # ช่องว่าง >=2 แต่ตัวไม่เหมือนกัน -> เหลือ space เดียว
                    out.append(" ")
                    i = j
                    continue
            else:
                # ช่องว่างเดียว -> คงไว้
                out.append(" ")
                i = j

    return "".join(out)


# ---------- 3) เดินทั้ง JSON dict/list ----------

def clean_json_values(value: Any) -> Any:
    """
    - ถ้าเป็น string -> ทำ normalize + fix_spaces_and_duplicate_chars
    - ถ้าเป็น dict  -> ทำซ้ำทุก value
    - ถ้าเป็น list  -> ทำซ้ำทุก element
    """
    if isinstance(value, str):
        return fix_spaces_and_duplicate_chars(value)
    if isinstance(value, dict):
        return {k: clean_json_values(v) for k, v in value.items()}
    if isinstance(value, list):
        return [clean_json_values(v) for v in value]
    return value
# ทำความสะอาด
cleaned = clean_json_values(a)

