import unicodedata

# เอาสตริงจริงของคุณมาใส่ตรงนี้
s = "เน้าหน้าน้สถา                   า"  # ค่อยไปเปลี่ยนทีหลังเป็น string จาก LLM ก็ได้
print('---------------')
print(s.replace("\u0020", "%"))
for i, ch in enumerate(s):
    code = ord(ch)
    print(
        i,                      # index
        repr(ch),               # รูป debug เช่น ' ' หรือ 'อ'
        f"\\u{code:04x}",       # โค้ด \uXXXX (สังเกตมี \\)
        unicodedata.name(ch, "?"),   # ชื่อ unicode ถ้ามี
        unicodedata.category(ch),    # category เช่น Zs, Cf, Lo, Mn
    )
